        expr: RELEASE_DATE
        data_type: VARCHAR(8)
        access_modifier: public_access
        description: Release date stored as a YYYYMMDD string. Use RELEASE_DATE_PARSED for any date math or filtering.
      - name: STUDIO
        expr: STUDIO
        data_type: VARCHAR(16777216)
        access_modifier: public_access
      - name: TITLE_ID
        expr: TITLE_ID
        data_type: NUMBER(38,0)
