  - name: MONTHLY_REVENUE
    description: 'Monthly digital game revenue: one row per TITLE_ID, REVENUE_MONTH and REVENUE_SOURCE (monetization type). This is the same revenue as DIGITAL_TRANSACTIONS pre-aggregated by month (totals match exactly); never add the two together.'
    base_table:
      database: CORTEX_SENSE_DEMO
      schema: GAME_SALES
      table: MONTHLY_REVENUE
    primary_key:
      columns:
        - TITLE_ID
        - REVENUE_MONTH
        - REVENUE_SOURCE
    dimensions:
      - name: TITLE_ID
        expr: TITLE_ID
        data_type: NUMBER(38,0)
      - name: REVENUE_SOURCE
        description: 'Monetization type of the revenue (BASE_GAME_DIGITAL, BASE_GAME_PHYSICAL, DLC, COSMETIC_MICROTRANSACTION, LOOT_BOX, CONSUMABLE_MICROTRANSACTION, BATTLE_PASS, VIRTUAL_CURRENCY). Not a lifecycle phase: there are no launch, ongoing, dlc_bump, seasonal or tail values. Derive phases from months since TITLES.RELEASE_DATE_PARSED.'
        expr: REVENUE_SOURCE
        data_type: VARCHAR
        sample_values:
          - BASE_GAME_DIGITAL
          - BASE_GAME_PHYSICAL
          - DLC
          - COSMETIC_MICROTRANSACTION
          - LOOT_BOX
          - CONSUMABLE_MICROTRANSACTION
          - BATTLE_PASS
          - VIRTUAL_CURRENCY
      - name: REVENUE_MONTH
        description: First day of the revenue month.
        expr: REVENUE_MONTH
        data_type: DATE
    facts:
