        description: Gross digital revenue for the title, month and monetization type.
        expr: MONTHLY_INCOME
        data_type: FLOAT
    metrics:
      - name: TOTAL_MONTHLY_INCOME
        description: Total gross digital game revenue from MONTHLY_REVENUE.
        expr: SUM(monthly_revenue.monthly_income_amt)
relationships:
