verified_queries:
  - name: What is digital revenue by title?
    question: What is digital revenue by title?
    sql: SELECT t.title_name, SUM(d.gross_revenue_amt) AS gross_revenue, SUM(d.net_developer_revenue_amt) AS net_developer_revenue FROM digital_transactions AS d JOIN digital_products AS p ON p.digital_product_id = d.digital_product_id JOIN titles AS t ON t.title_id = p.title_id GROUP BY t.title_name ORDER BY gross_revenue DESC NULLS LAST
    verified_at: 1792706574
    use_as_onboarding_question: true
  - name: What is digital revenue by title code?
    question: What is digital revenue by title code?
    sql: SELECT x.title_code, t.title_name, sp.platform_name, SUM(d.gross_revenue_amt) AS gross_revenue, SUM(d.net_developer_revenue_amt) AS net_developer_revenue FROM digital_transactions AS d JOIN digital_products AS p ON p.digital_product_id = d.digital_product_id JOIN sales_platforms AS sp ON sp.platform_id = d.platform_id JOIN title_code_xref AS x ON x.title_id = p.title_id AND x.platform_code = sp.platform_code JOIN titles AS t ON t.title_id = p.title_id GROUP BY x.title_code, t.title_name, sp.platform_name ORDER BY gross_revenue DESC NULLS LAST
    verified_at: 1792706574
  - name: What is digital revenue by monetization type?
    question: What is digital revenue by monetization type?
    sql: SELECT rt.monetization_type, SUM(d.gross_revenue_amt) AS gross_revenue, SUM(d.net_developer_revenue_amt) AS net_developer_revenue, COUNT(d.transaction_id) AS transactions FROM digital_transactions AS d JOIN digital_products AS p ON p.digital_product_id = d.digital_product_id JOIN revenue_types AS rt ON rt.category_id = p.category_id GROUP BY rt.monetization_type ORDER BY gross_revenue DESC NULLS LAST
    verified_at: 1792706574
  - name: What is total spend per customer across digital, hardware and subscriptions?
    question: What is total spend per customer across digital, hardware and subscriptions?
    sql: WITH dg AS (SELECT player_id AS customer_id, SUM(gross_revenue_amt) AS digital_spend FROM digital_transactions GROUP BY player_id), hw AS (SELECT buyer_id AS customer_id, SUM(hw_gross_revenue_amt) AS hardware_spend FROM hardware_sales GROUP BY buyer_id), sb AS (SELECT subscriber_id AS customer_id, SUM(sub_gross_revenue_amt) AS subscription_spend FROM subscription_charges GROUP BY subscriber_id) SELECT c.customer_id, c.region, COALESCE(dg.digital_spend, 0) AS digital_spend, COALESCE(hw.hardware_spend, 0) AS hardware_spend, COALESCE(sb.subscription_spend, 0) AS subscription_spend, COALESCE(dg.digital_spend, 0) + COALESCE(hw.hardware_spend, 0) + COALESCE(sb.subscription_spend, 0) AS total_spend FROM customers AS c LEFT JOIN dg ON dg.customer_id = c.customer_id LEFT JOIN hw ON hw.customer_id = c.customer_id LEFT JOIN sb ON sb.customer_id = c.customer_id ORDER BY total_spend DESC NULLS LAST
    verified_at: 1792706574
  - name: What is total company revenue by revenue stream?
    question: What is total company revenue by revenue stream?
    sql: SELECT revenue_stream, gross_revenue, gross_revenue / SUM(gross_revenue) OVER () AS share_of_total FROM (SELECT 'Hardware' AS revenue_stream, SUM(hw_gross_revenue_amt) AS gross_revenue FROM hardware_sales UNION ALL SELECT 'Subscriptions' AS revenue_stream, SUM(sub_gross_revenue_amt) AS gross_revenue FROM subscription_charges UNION ALL SELECT 'Digital game sales' AS revenue_stream, SUM(gross_revenue_amt) AS gross_revenue FROM digital_transactions) AS streams ORDER BY gross_revenue DESC NULLS LAST
    verified_at: 1792718899
  - name: What is digital revenue in the launch month, early life and tail?
    question: What is digital revenue in the launch month, early life and tail?
    sql: SELECT CASE WHEN DATEDIFF(MONTH, DATE_TRUNC('MONTH', t.release_date_parsed), m.revenue_month) = 0 THEN 'Launch month' WHEN DATEDIFF(MONTH, DATE_TRUNC('MONTH', t.release_date_parsed), m.revenue_month) BETWEEN 1 AND 5 THEN 'Early life (months 1-5)' ELSE 'Tail (month 6+)' END AS lifecycle_phase, SUM(m.monthly_income_amt) AS revenue, COUNT(DISTINCT m.title_id) AS titles FROM monthly_revenue AS m JOIN titles AS t ON t.title_id = m.title_id GROUP BY 1 ORDER BY MIN(DATEDIFF(MONTH, DATE_TRUNC('MONTH', t.release_date_parsed), m.revenue_month))
    verified_at: 1792720150
module_custom_instructions:
  sql_generation: 'Digital revenue: get the title of a digital transaction through its product (DIGITAL_TRANSACTIONS -> DIGITAL_PRODUCTS -> TITLES via PRODUCT_TITLE). There is no direct transaction-to-title relationship. DIGITAL_TRANSACTIONS.TITLE_ID is NULL for about 10% of revenue, while DIGITAL_PRODUCTS.TITLE_ID is always populated and agrees wherever both exist. TITLE_CODE_XREF has one row per title and platform and only contains PlayStation codes: never join it to revenue on TITLE_ID alone; join on both title and platform (via SALES_PLATFORMS.PLATFORM_CODE). Revenue by title code covers only PlayStation sales and must not be used as total revenue. When combining digital, hardware and subscription revenue per customer, aggregate each fact table separately before joining to CUSTOMERS. MONTHLY_REVENUE is the same digital game revenue as DIGITAL_TRANSACTIONS (it totals the same). Use it for monthly trends and lifecycle phases, but never add it to DIGITAL_TRANSACTIONS revenue or include both in total company revenue. Its REVENUE_SOURCE is the monetization type, not a lifecycle phase; derive launch, early-life and tail phases from months since TITLES.RELEASE_DATE_PARSED (0 = launch month, 1-5 = early life, 6+ = tail). Total company revenue is hardware + subscription + digital gross revenue, each summed separately.'

$$, FALSE, FALSE);

